fs.writeFileSync(path.join(d, "lib/h.mjs"), "export const h=1;");
fs.writeFileSync(path.join(d, "sib.cjs"), "module.exports={s:1}");
fs.writeFileSync(path.join(ws, "evil.mjs"), "globalThis.__EVIL=(globalThis.__EVIL||0)+1; export default {name:'evilabs',description:'x'}");
fs.writeFileSync(path.join(ws, "data.txt"), "secret");
const P: Record<string,string> = {
 "a_rel.mjs": "import {h} from './lib/h.mjs'; export default {name:'a_rel',description:'ok'+h};",
 "b_req.js": "const s=require('./sib.cjs'); module.exports={name:'b_req',description:'ok'+s.s};",
 "c_dyn.mjs": `const m=await import(${JSON.stringify(path.join(ws,"evil.mjs"))}); export default {name:'c_dyn',description:'ran '+m.default.name};`,
 "d_dyn_rel.mjs": "const m=await import('./lib/h.mjs'); export default {name:'d_dyn_rel',description:'ok'};",
 "e_meta.mjs": "import fs from 'node:fs'; let r; try{r=fs.readFileSync(new URL('./sib.cjs',import.meta.url),'utf8')}catch(e){r='ENOENT'} export default {name:'e_meta',description:'read:'+r};",
 "f_cr.mjs": "import {createRequire} from 'node:module'; const rq=createRequire(import.meta.url); let r; try{r=rq('./sib.cjs')}catch(e){r='fail:'+e.code} export default {name:'f_cr',description:String(JSON.stringify(r))};",
 "g_bare.mjs": "let r; try{await import('wsdep'); r='found'}catch(e){r='fail:'+e.code} export default {name:'g_bare',description:r};",
 "h_bare.js": "let r; try{require('wsdep'); r='found'}catch(e){r='fail:'+e.code} module.exports={name:'h_bare',description:r};",
 "i_info.mjs": `import fs from 'node:fs'; import path from 'node:path'; const dn=path.dirname(new URL(import.meta.url).pathname); const st=fs.statSync(dn); export default {name:'i_info',description:'dir='+dn.replace(/nexus-plugin-[^/]*/,'TMP')+' mode='+(st.mode&0o777).toString(8)+' ls='+fs.readdirSync(dn)+' parent='+path.dirname(dn)+' stack='+new Error().stack.split('\\n')[1].replace(/nexus-plugin-[^/]*/,'TMP')};`,
 "j_esm_js.js": "export default {name:'j_esm_js',description:'esm in .js'};",
 "k_bom.mjs": "\ufeffexport default {name:'k_bom',description:'bom'};",
 "l_badutf.mjs": "x",
};
for (const [n, b] of Object.entries(P)) { fs.writeFileSync(path.join(d, n), b); }
fs.writeFileSync(path.join(d, "l_badutf.mjs"), Buffer.concat([Buffer.from("export default {name:'l_badutf',description:'"), Buffer.from([0xff,0xfe]), Buffer.from("'};")]));
const approve = (p: string) => { const id = workspacePluginTrustId(ws, p); approveExtension({ kind: "workspace-plugin", scope: id.scope, key: id.key, sha256: pluginFileSha256(p), approvedAt: new Date().toISOString(), summary: "p" }); };
for (const n of [...Object.keys(P)]) approve(path.join(d, n));
const pm = new PluginManager(ws); await pm.loadPlugins();
for (const p of pm.listPlugins()) console.log(p.name, "=>", p.description);
console.log("not loaded:", pm.getPluginTrustRecords().filter(r=>!pm.listPlugins().find(p=>p.name===r.name)).map(r=>path.basename(r.path)+":"+r.status));
console.log("EVIL global", (globalThis as any).__EVIL);
console.log("tmp leftovers:", fs.readdirSync(os.tmpdir()).filter(x=>x.startsWith("nexus-plugin-")).length);
EOF
HOME=$(mktemp -d) TMPDIR=/dev/shm node --import tsx _sib_probe.ts 2>&1 | tail -30

